        for(const auto &row:grid){
            for(const int &x:row){
                linear.push_back(x);
            }
        }
        int m=grid.size();
        int n=grid[0].size();
        k%=(m*n);
        reverse(linear.begin(),linear.end());
        reverse(linear.begin(),linear.begin()+k);
