            }
        }

        return p1 == m;  
    }
};

class Solution {
public:
    int mySqrt(int x) {
        if(x==0 || x==1)return x;

        int low=1,high=x/2;
        int result=1;
        while(low<=high){
            long long mid=low+(high-low)/2;
            if(mid*mid<=x){
                result=mid;
                low=mid+1;
            }
            else{
                high=mid-1;
            }
        }
        return result;
    }
};

class Solution {
public:
    int row(char ch){
        ch=(char)tolower(ch);
        int res;
        switch(ch){
            case 'q':case 'w':case 'e':case 'r':case 't':case 'y':case 'u':case 'i':case 'o':case 'p':
            res=1;
            break;
            case 'a':case 's':case 'd':case 'f':case 'g':case 'h':case 'j':case 'k':case 'l':
            res=2;
            break;
            case 'z':case 'x':case 'c':case 'v':case 'b':case 'n':case 'm':
            res=3;
            break;
            default:
            res=-1;
        }
        return res;
    }
    bool isSameRow(string word){
        int n=word.size();
        int base=row(word[0]);
        for(int i=1;i<n;i++){
            if(row(word[i])!=base){
                return false;
            }
        }
        return true;
    }
    vector<string> findWords(vector<string>& words) {
         vector<string> result;
         for(const auto &word : words){
            if(isSameRow(word)){
                result.push_back(word);
            }
         }
         return result;
    }
};

class Solution {
public:
    int findKOr(vector<int>& nums, int k) {
        int ans=0;
        for(int b=0;b<32;b++){
            int count=0;
            for(int x:nums){
                if(((x>>b)&1)==1){
                    count++;
                }
            }
            if(count>=k){
                ans|=(1<<b);
            }
        }
        return ans;

    }
};

class Solution {
public:
    int repeatedNTimes(vector<int>& nums) {
        int n = nums.size();
        for(int i = 0; i < n; i++) {
            if(i + 1 < n && nums[i] == nums[i + 1]){
                return nums[i];
            }
            if(i + 2 < n && nums[i] == nums[i + 2]){
                return nums[i];
            }
            if(i + 3 < n && nums[i] == nums[i + 3]){
                return nums[i];
            }
        }
        return -1;
    }
};

class Solution {
public:
    int generateKey(int num1, int num2, int num3) {
        int place = 1;
        int res = 0;

        for(int i=0;i<4;i++)
        {
            int d1 = num1%10;
            int d2 = num2%10;
            int d3 = num3%10;

            int min = std::min(d1, std::min(d2,d3));
            res += (min*place);

            num1 /= 10;
            num2 /= 10;
            num3 /= 10;

            place *= 10;
        }
        return res;
    }
};

class Solution {
public:
    vector<int> separateDigits(vector<int>& nums) {
        vector<int> result;
        for(auto &x : nums){
            stack<int> rev;
            while(x){
                rev.push(x%10);
                x/=10;
            }
            while(!rev.empty()) {
                result.push_back(rev.top());
                rev.pop();
            }
        }
        return result;
    }
};

class Solution {
public:
    int minCostClimbingStairs(vector<int>& cost) {
        int n = cost.size();
        vector<int> dp(n);
        dp[0] = cost[0];
        dp[1] = cost[1];
        for(int i = 2; i < n; i++){
            dp[i] = cost[i] + std::min(dp[i-1], dp[i-2]);     
        }
        return std::min(dp[n-1],dp[n-2]);
    }
};

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        vector <pair<int,int>> nums_with_index;
        for(int i=0;i<nums.size();i++){
            nums_with_index.emplace_back(nums[i],i);
        }
        sort(nums_with_index.begin(),nums_with_index.end());
        int l=0,r=nums_with_index.size()-1;
        while(l<=r){
            int sum=nums_with_index[l].first+nums_with_index[r].first;
            if(sum>target){
                r--;
            }
            else if(sum<target){
                l++;
            }
            else if(sum==target){
                return {nums_with_index[l].second,nums_with_index[r].second};
            }
        }
        return {-1,-1};
    }
};

class Solution {
public:
    int getMaximumGenerated(int n) {
        if (n == 0) return 0;

        vector<int> nums(n + 1);
        nums[0] = 0;
        nums[1] = 1;
        int maxVal = 1;

        for (int i = 1; 2 * i <= n; i++) {
            nums[2 * i] = nums[i];
            maxVal = max(maxVal, nums[2 * i]);

            if (2 * i + 1 <= n) {
                nums[2 * i + 1] = nums[i] + nums[i + 1];
                maxVal = max(maxVal, nums[2 * i + 1]);
            }
        }

        return maxVal;
    }
};

class Solution {
public:
    double findMaxAverage(vector<int>& nums, int k) {
        int n = nums.size();
        int l = 0, r = k - 1;
        long long sum = 0;
        for(int i = 0; i < k; i++){
            sum += nums[i];
        }
        long long maxSum = sum;
        while(r + 1 <= n - 1){
            sum -= nums[l++];
            sum += nums[++r];
            maxSum = std::max(sum, maxSum);
        }
        return (double)maxSum / k;
    }
};

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int l = 0;
        int maxLength = 0;
        unordered_set<char> currentWindow;

        for(int r = 0; r < s.size(); r++){
            while(currentWindow.contains(s[r])){
                currentWindow.erase(s[l++]);
            }
            currentWindow.insert(s[r]);
            maxLength = std::max(r - l + 1, maxLength);
        }
        return maxLength;
    }
};

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = nums.size();
        int minLength = n + 1;
        long long windowSum = 0;
        int l = 0;
        for(int r = 0; r < n; r++){
            windowSum += nums[r];
            while(windowSum >= target){
                minLength = std::min(r - l + 1, minLength);
                windowSum -= nums[l++];
            }
        }
        if(minLength == n + 1) return 0;
        return minLength;
    }
};

class Solution {
public:
    int characterReplacement(string s, int k) {
        int l = 0, maxFreq = 0, maxLength = 0;
        unordered_map<char, int> freq;

        for(int r = 0; r < s.size(); r++){
            freq[s[r]]++;
            maxFreq = std::max(maxFreq, freq[s[r]]);
            while(r - l  + 1 - maxFreq > k){
                freq[s[l]]--;
                l++;
            }
            maxLength = std::max(maxLength, r - l + 1);
        }

        return maxLength;
    }
};
